class InfoExtractor(BaseComponent):
    def __init__(self, config: ComponentConfig):
        self.config = config

    def forward(self, *, rewritten_query: str, **_) -> dict:
        prompt = f"{self.config.prompt_template}\n\nQuery: {rewritten_query}\n\nKeywords:"
        resp = llm_call(
            prompt,
            model=self.config.model,
            max_tokens=self.config.max_tokens,
            temperature=self.config.temperature,
        )
        # Clean and join keywords into a single string for retrieval
        lines = resp.text.strip().splitlines()
        keywords = []
        for line in lines:
            line = line.strip()
            if not line:
                continue
            # Remove common bullet points or numbering
            if line[0] in "-*•" or line[:2].isdigit():
                line = line.lstrip("-*•0123456789. ").strip()
            keywords.append(line)
        search_keywords = ", ".join(keywords) if keywords else resp.text.strip()
        return {"search_keywords": search_keywords}

